const camposDe=t=>{const C=CENS();if(!C)return[];const ks=new Set(C.campos.map(c=>c.k)),out=[];SYN.forEach(([k,re])=>{if(re.test(t)&&ks.has(k)&&!out.includes(k))out.push(k)});
 if(out.includes('poblacion')&&out.some(k=>k!=='poblacion'&&/pobl|indig|mayor|menor|edad/.test(k))&&/(indigena|mayores|menores|edad)/.test(t))return out.filter(k=>k!=='poblacion');if(out.includes('tasa_empleo')&&out.includes('tasa_desocupacion'))return out.filter(k=>k!=='tasa_empleo');if(out.includes('sin_cobertura')&&out.includes('rama_salud'))return out.filter(k=>k!=='sin_cobertura');return out};
