const numF=v=>Number.isInteger(v)?Math.round(v).toLocaleString('es-AR'):f1(v);
function fmtC(v,c){const u=c.u||'';if(/^%/.test(u))return f1(v)+' por ciento'+(u.replace(/^%\s*/,'')?' '+u.replace(/^%\s*/,''):'');if(u==='hab.')return numF(v)+' habitantes';if(u==='km²')return numF(v)+' kilómetros cuadrados';if(u==='hab/km²')return f1(v)+' habitantes por kilómetro cuadrado';if(u==='años')return f1(v)+' años';if(u==='pers.')return numF(v)+' personas';if(u==='viv.')return numF(v)+' viviendas';return numF(v)+(u?' '+u:'')}
