function rankear(key,desc){const C=CENS();return Object.keys(C.deptos).filter(k=>typeof C.deptos[k][key]==='number').map(k=>({k,v:C.deptos[k][key]})).sort((a,b)=>desc===false?a.v-b.v:b.v-a.v)}
function frase(k,key,breve){const C=CENS(),c=campoDe(key),v=C.deptos[k]&&C.deptos[k][key];if(typeof v!=='number')return DNOM(k)+': sin dato de '+(c?c.t.toLowerCase():key)+'.';const r=rankear(key),pos=r.findIndex(x=>x.k===k)+1,pv=C.provincia&&C.provincia[key];
 let s=c.t+' en '+DNOM(k)+': '+fmtC(v,c)+'.';if(!breve){if(typeof pv==='number'&&key!=='poblacion'&&key!=='superficie'&&key!=='viviendas'&&key!=='hogares')s+=' El promedio de la provincia es '+fmtC(pv,c)+'.';if(r.length>1)s+=' Es el '+ordinal(pos)+' de '+r.length+' departamentos'+(pos===1?', el más alto.':pos===r.length?', el más bajo.':'.')}return s}
function indProv(re){const I=S.ind&&S.ind.indicadores?S.ind.indicadores:[];const x=I.find(i=>re.test(norm(i.titulo)));if(!x)return null;const d=new Date(x.ultimo.periodo||x.ultimo.fecha);return{t:x.titulo,v:x.ultimo.valor,per:isNaN(d)?String(x.ultimo.periodo):d.toLocaleDateString('es-AR',{month:'long',year:'numeric'})}}
