/* --- entidades: nombres → persona con identificador; nunca se elige a ciegas si hay varias --- */
function candP(q){const ws=norm(q).split(' ').filter(w=>w.length>1&&!STOPW.has(w));if(!ws.length)return[];const out=[];personas.forEach(p=>{const nm=norm([p.nombre,...(p.aliases||[])].join(' ')).split(' ');let s=0,ex=0;for(const w of ws){const m=Math.max(0,...nm.map(x=>x===w?4:x.startsWith(w)&&w.length>=4?3:(typeof wsc==='function'&&w.length>=4?wsc(w,x):0)));if(!m){s=-1;break}s+=m;if(m===4)ex++}if(s>0)out.push({p,s,full:ex===ws.length})});return out.sort((a,b)=>b.s-a.s)}
function resolverP(q){const c=candP(q);if(!c.length)return{none:true};const ex=c.filter(x=>x.full),pool=ex.length?ex:c;if(pool.length===1)return ex.length?{p:pool[0].p}:{p:pool[0].p,aprox:true};return{cands:pool.slice(0,5).map(x=>x.p)}}
const etqP=p=>p.nombre+' ('+esCargo(p)+(p.v===0?', no vigente':'')+')';
