function start(){if(!SR){show('','Este navegador no tiene reconocimiento de voz. Usá Chrome, Edge o Safari, o escribí la orden en el cuadro.',false);abrir(true);return}
 if(oyendo||hablando)return;blocked=false;quiere=true;rec=new SR();rec.lang='es-AR';rec.continuous=!!CFG.hf;rec.interimResults=true;rec.maxAlternatives=5;let hecho=-1;
 rec.onstart=()=>{ui(true);fails=0;estado('escuchando');show('',CFG.hf?'Escucho. Decí «Newar» y tu orden.':'Te escucho…',null);clearTimeout(wd);if(!CFG.hf)wd=setTimeout(()=>{if(oyendo){show('','No escuché nada. Probá de nuevo o escribí la orden.',false);estado('error','silencio');stop()}},12000)};
 rec.onresult=e=>{clearTimeout(wd);for(let i=e.resultIndex;i<e.results.length;i++){const r=e.results[i];if(!r.isFinal){show(r[0].transcript,'…',null);continue}if(i<=hecho)continue;hecho=i;const alts=Array.from(r).map(a=>a.transcript).filter(Boolean);if(!alts.length)continue;
   if(buf.length&&norm(buf[buf.length-1].alts[0])===norm(alts[0]))continue;buf.push({alts,conf:r[0].confidence});clearTimeout(bufT);
   bufT=setTimeout(()=>{const b=buf;buf=[];Promise.resolve(procesar(b)).then(()=>{if(!CFG.hf){quiere=false;try{rec.stop()}catch(x){}}})},CFG.hf?800:450)}};
 rec.onerror=e=>{const c=e.error;if(c==='no-speech'){show('','No escuché nada. Probá de nuevo o escribí la orden.',false);estado('error','silencio')}else if(c==='not-allowed'||c==='service-not-allowed'){blocked=true;quiere=false;CFG.hf=0;estado('error','permiso denegado');show('','El navegador no dio permiso al micrófono. Habilitalo desde el candado de la barra de direcciones, o escribí la orden en el cuadro.',false)}else if(c==='audio-capture'){blocked=true;quiere=false;show('','No encuentro un micrófono.',false)}else if(c==='network'){fails++;show('','Falló la conexión del servicio de voz del navegador'+(fails>2?'. Probá escribir las órdenes.':'; reintento…'),false);if(fails>4){quiere=false}}};
 rec.onend=()=>{clearTimeout(wd);ui(false);if(!blocked&&$('#nvst')&&$('#nvst').dataset.estado==='escuchando')estado('listo');if(quiere&&CFG.hf&&!blocked&&!hablando)setTimeout(()=>{if(quiere&&!oyendo)start()},fails>2?2500:300)};
 try{rec.start()}catch(e){ui(false)}}
function stop(){quiere=false;clearTimeout(wd);try{rec&&rec.stop()}catch(e){}ui(false);if($('#nvst')&&$('#nvst').dataset.estado==='escuchando')estado('listo')}
function cancelar(){quiere=false;clearTimeout(wd);clearTimeout(bufT);buf=[];pend=null;pend2=null;cancelaHabla();try{rec&&rec.abort()}catch(e){}ui(false);estado('listo','cancelado');show('','Cancelado.',null)}
const abrir=v=>{const a=v==null?pan.hidden:v;pan.hidden=!a;if(a){ui();cargaVoces();$('#nvin').focus()}};
function ayuda(forzar){const h=$('#nvh');if(forzar||h.hidden){h.hidden=false;h.innerHTML=`<h4>En el mapa</h4><code>acercá el mapa</code><code>estadísticas de Orán</code><code>decime la población y la pobreza de Orán</code><code>qué departamento tiene más población</code><code>compará Orán con San Martín</code><code>senadores de Cafayate</code><code>notas de Orán</code><code>pintá el mapa por cloacas</code><code>mostrá toda la provincia</code><code>qué estoy viendo</code><h4>Hablame normal</h4><code>quiero ver los números de los medios</code><code>llevame a donde están los legisladores</code><code>cómo viene Sáenz</code><code>qué onda con la minería</code><code>abrí estadísticas y poné solo nacionales</code><code>sí / no</code> (para responder a lo que te propongo)<h4>Gráficos</h4><code>graficá las menciones de Gustavo Sáenz en los últimos 30 días</code><code>gráfico de notas por medio</code><code>gráfico de los temas de esta semana</code><code>graficá nacionales contra Salta</code><h4>Preguntas</h4><code>¿cuántas notas hay hoy?</code><code>¿quién es el más mencionado esta semana?</code><code>¿qué temas se hablan?</code><code>¿qué dicen de Sáenz?</code><code>¿quién es Sáenz?</code><code>¿cuántos diputados tiene Todos por Salta?</code><code>¿quién tiene la mayoría en el Senado?</code><code>¿están los datos actualizados?</code><code>novedades de mis seguidos</code>
<h4>Moverse</h4><code>ir a mapa</code><code>abrir pulso</code><code>estadísticas</code><code>volver</code><code>arriba</code><code>bajar</code><code>hemiciclo del senado</code>
<h4>Personas</h4><code>ficha de Sáenz</code><code>su red</code><code>estrategia de Sáenz</code><code>informe de Sáenz</code><code>armá la consulta de Sáenz para debate</code><code>comparar Sáenz con Dib Ashur</code><code>camino entre Sáenz y Dib Ashur</code><code>seguir a Sáenz</code>
<h4>Pantalla actual</h4><code>solo nacionales</code><code>últimos 7 días</code><code>últimas 6 horas</code><code>mostrar más</code><code>descargar CSV</code><code>elegir más mencionados</code><code>escribir litio</code><code>tocá comparar</code>
<h4>Escuchar y herramientas</h4><code>resumen del día</code><code>leé los titulares</code><code>siguiente</code><code>leé la pantalla</code><code>repetí</code><code>callate</code><code>anotar llamar a prensa</code><code>temporizador de 5 minutos</code><code>calculá 15 por ciento de 2300</code><code>qué hora es</code>
<h4>Voz y modos</h4><code>mejor voz</code><code>voz de hombre</code><code>voz de mujer</code><code>modo Jarvis</code><code>hablá más rápido</code><code>cambiá la voz</code><code>no me respondas en voz</code><code>sala de control</code><code>rotar</code><code>tema claro</code>
<p class="note">Después de «Newar» podés seguir hablando unos segundos sin repetirlo. También respondo a «Jarvis». Si el navegador escribe «Neward» o «Nuar», igual te entiendo. Pronombres: después de hablar de alguien, «su ficha», «su red», «seguilo» o «su informe» usan a esa persona. El reconocimiento lo hace tu navegador; en Chrome y Edge el audio pasa por un servicio de voz en la nube. NEWAR no guarda audio.</p>`}else h.hidden=true}
$('#nvsup').textContent=(SR?'Reconocimiento disponible ('+(window.SpeechRecognition?'SpeechRecognition':'webkitSpeechRecognition')+'). No se activa solo: hay que tocar el micrófono. En Chrome y Edge el audio lo procesa un servicio de voz externo del navegador; NEWAR no graba ni guarda audio. ':'Este navegador no reconoce voz: usá el cuadro de texto (el teclado funciona igual). ')+(TTS?'Voz de respuesta disponible.':'Este navegador no puede hablar.');ui();estado('listo');
fab.addEventListener('click',()=>{if(hablando){cancelaHabla();return}abrir()});
pan.addEventListener('click',e=>{const b=e.target.closest('[data-nv]');if(!b)return;const a=b.dataset.nv;
 if(a==='close')abrir(false);else if(a==='help')ayuda();else if(a==='talk')oyendo?stop():start();else if(a==='shh'){cancelaHabla();colaLect=[]}else if(a==='cancel')cancelar();else if(a==='fix'){const i=$('#nvin');i.value=ultimaTrans||i.value;i.focus();i.select();estado('aclaracion','corregí la transcripción y apretá Enter')}
 else if(a==='test'){const m='Hola, soy NEWAR. Así suena mi voz.';const s=CFG.say;CFG.say=1;say(m).then(()=>{CFG.say=s})}
 else if(a==='hf'){CFG.hf=CFG.hf?0:1;save();ui();if(oyendo)stop();if(CFG.hf){start();const m='Modo manos libres. Decí Newar y tu orden.';show('',m,true);say(m)}else show('','Manos libres apagado.',true)}
 else if(a==='run'){const i=$('#nvin');if(i.value.trim()){run(i.value.trim());i.value=''}}});
$('#nvin').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const i=e.target;if(i.value.trim()){run(i.value.trim());i.value=''}}else if(e.key==='Escape'){if(oyendo||hablando||pend2)cancelar();else abrir(false)}});
const tg=(id,k)=>$('#'+id).addEventListener('change',e=>{CFG[k]=e.target.checked?1:0;save()});tg('nvsay','say');tg('nvconf','conf');tg('nvwake','wake');tg('nvnarra','narra');
