document.addEventListener('keydown',e=>{if(e.altKey&&!e.ctrlKey&&!e.metaKey&&(e.code==='KeyV'||e.key==='v'||e.key==='V')){e.preventDefault();if(hablando)cancelaHabla();else if(oyendo)stop();else{abrir(true);start()}}});
